import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.Dkj3JE0_.js";const p=JSON.parse('{"title":"Plan CFA niveau II","description":"","frontmatter":{"title":"Plan CFA niveau II"},"headers":[],"relativePath":"fr/blogs/CFA/plan.md","filePath":"fr/blogs/CFA/plan.md"}'),i={name:"fr/blogs/CFA/plan.md"};function n(o,e,l,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="plan-d-apprentissage-du-cfa-niveau-ii" tabindex="-1">Plan d’apprentissage du CFA niveau II <a class="header-anchor" href="#plan-d-apprentissage-du-cfa-niveau-ii" aria-label="Permalink to &quot;Plan d’apprentissage du CFA niveau II&quot;">​</a></h1><blockquote><p><strong>Hypothèse de travail :</strong> examen le <strong>mercredi 18 novembre 2026</strong>. Sprint intensif jusqu’au <strong>31 octobre</strong> (~<strong>40 heures par semaine</strong>, FSA d’abord) pour terminer le programme restant, puis <strong>1er–16 novembre</strong> pour la révision et <strong>3–4 examens blancs</strong>, avec seulement du travail léger les <strong>17–18 novembre</strong>. Ne pas sacrifier la phase examens blancs et révision.</p></blockquote><h2 id="criteres-d-achevement" tabindex="-1">Critères d’achèvement <a class="header-anchor" href="#criteres-d-achevement" aria-label="Permalink to &quot;Critères d’achèvement&quot;">​</a></h2><ul><li>Terminer un premier passage de chaque matière restante d’ici le <strong>vendredi 31 octobre</strong> (Actions, Obligations, Gestion de portefeuille, Émetteurs, Placements alternatifs, plus les restes de FSA et d’Éthique).</li><li>Faire les questions de fin de lecture de chaque module étudié ; tenir un seul carnet compact de formules et d’erreurs, pas un deuxième manuel.</li><li>Passer <strong>3–4 examens blancs chronométrés</strong> (dates ci-dessous) et consacrer à chacun au moins autant de temps de révision que de temps d’épreuve ; la FSA d’abord chaque semaine de révision.</li><li>Aborder la semaine d’examen sans matière qui s’effondre régulièrement sous contrainte de temps ; protéger le sommeil les 17–18 novembre.</li></ul><h2 id="priorites-actuelles-au-14-oct-2026" tabindex="-1">Priorités actuelles (au 14 oct. 2026) <a class="header-anchor" href="#priorites-actuelles-au-14-oct-2026" aria-label="Permalink to &quot;Priorités actuelles (au 14 oct. 2026)&quot;">​</a></h2><p><strong>Déjà fait (pas de premier passage nécessaire) :</strong> Dérivés, Méthodes quantitatives.</p><p><strong>Partiel :</strong> Économie, environ la moitié restante. Éthique en cours — normes I(C), I(D), I(E) et II(A) couvertes.</p><p><strong>En cours :</strong> FSA module 1 (Investissements intersociétés), jusqu’à l’exemple de base de la mise en équivalence (participation à 118 après dividende). En retard sur le programme idéal « fin de M1 + début de M2 » — soirées de rattrapage jusqu’à dimanche.</p><p><strong>Premier passage non commencé :</strong> Actions, Obligations, Gestion de portefeuille, Émetteurs, Placements alternatifs. Point le plus faible = FSA.</p><p><strong>Prochaines actions :</strong> finir les questions de fin de chapitre de M1 → <strong>M2 Rémunération des salariés</strong> → M3–M6 (des ébauches suffisent pendant le rattrapage) + restes d’Éthique + boucler la moitié restante d’Économie.</p><h2 id="rythme-hebdomadaire-jours-ouvres" tabindex="-1">Rythme hebdomadaire (jours ouvrés) <a class="header-anchor" href="#rythme-hebdomadaire-jours-ouvres" aria-label="Permalink to &quot;Rythme hebdomadaire (jours ouvrés)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bloc</th><th style="text-align:right;">Horaire</th><th>Travail</th></tr></thead><tbody><tr><td>CFA du soir</td><td style="text-align:right;">20:00–02:00</td><td>Bloc principal de programme et d’exercices.</td></tr><tr><td>Sport</td><td style="text-align:right;">18:00–20:00</td><td>Personnel — pas de CFA.</td></tr><tr><td>Rapport hebdo</td><td style="text-align:right;">lun. 08:00–10:00</td><td>Administratif du travail — pas de CFA.</td></tr></tbody></table><p>Les quiz Animus seulement après la vérification des notes de <strong>02:00</strong> ou une clôture explicite de la journée — pas en pleine session.</p><p>Dans le bloc CFA, répartition <strong>40/60</strong> : pas plus de 40 % de lecture ; au moins 60 % de rappel, de calcul et d’études de cas.</p><h2 id="feuille-de-route-intensive" tabindex="-1">Feuille de route intensive <a class="header-anchor" href="#feuille-de-route-intensive" aria-label="Permalink to &quot;Feuille de route intensive&quot;">​</a></h2><h3 id="phase-1-—-finir-le-programme-12–31-oct-·-40-h-sem-·-fsa-d-abord" tabindex="-1">Phase 1 — Finir le programme (12–31 oct. · ~40 h/sem. · FSA d’abord) <a class="header-anchor" href="#phase-1-—-finir-le-programme-12–31-oct-·-40-h-sem-·-fsa-d-abord" aria-label="Permalink to &quot;Phase 1 — Finir le programme (12–31 oct. · ~40 h/sem. · FSA d’abord)&quot;">​</a></h3><h4 id="cette-semaine-13–18-oct" tabindex="-1">Cette semaine (13–18 oct.) <a class="header-anchor" href="#cette-semaine-13–18-oct" aria-label="Permalink to &quot;Cette semaine (13–18 oct.)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Priorité</th><th style="text-align:right;">Heures</th><th>Objectif d’ici dim. 18 oct.</th></tr></thead><tbody><tr><td>FSA en profondeur</td><td style="text-align:right;">22–24</td><td>≥80–100 % du premier passage + questions de fin de chapitre</td></tr><tr><td>Reste de l’Éthique</td><td style="text-align:right;">6–8</td><td>Normes après II(A) entamées</td></tr><tr><td>Clôture de l’Économie</td><td style="text-align:right;">3–4</td><td>Moitié restante bouclée</td></tr></tbody></table><h4 id="semaine-du-19-au-25-oct" tabindex="-1">Semaine du 19 au 25 oct. <a class="header-anchor" href="#semaine-du-19-au-25-oct" aria-label="Permalink to &quot;Semaine du 19 au 25 oct.&quot;">​</a></h4><ul><li>Actions : premier passage complet.</li><li>Obligations : majeure partie du premier passage.</li><li>Consolidation FSA : 6–8 heures d’exercices variés.</li></ul><h4 id="semaine-du-26-au-31-oct" tabindex="-1">Semaine du 26 au 31 oct. <a class="header-anchor" href="#semaine-du-26-au-31-oct" aria-label="Permalink to &quot;Semaine du 26 au 31 oct.&quot;">​</a></h4><ul><li>Finir les Obligations.</li><li>Gestion de portefeuille, Émetteurs, Placements alternatifs.</li><li>Études de cas d’Éthique.</li><li><strong>Programme terminé d’ici le vendredi 31 octobre.</strong></li></ul><h3 id="phase-2-—-revision-et-examens-blancs-1er–16-nov" tabindex="-1">Phase 2 — Révision et examens blancs (1er–16 nov.) <a class="header-anchor" href="#phase-2-—-revision-et-examens-blancs-1er–16-nov" aria-label="Permalink to &quot;Phase 2 — Révision et examens blancs (1er–16 nov.)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Examen blanc</th><th>Date</th><th>Note</th></tr></thead><tbody><tr><td>Blanc 1</td><td>sam. 1er nov.</td><td>Complet et chronométré ; FSA d’abord à la correction.</td></tr><tr><td>Blanc 2</td><td>sam. 8 nov.</td><td>Complet et chronométré ; réparer les deux matières les plus faibles en milieu de semaine.</td></tr><tr><td>Blanc 3</td><td>mer. 12 nov.</td><td>Complet et chronométré.</td></tr><tr><td>Blanc 4 (facultatif)</td><td>sam. 15 nov.</td><td>Seulement si l’énergie et le retard de correction le permettent.</td></tr></tbody></table><p>Chaque semaine de révision : la FSA d’abord, puis les matières les moins bien notées au dernier examen blanc. Refaire les erreurs consignées ; réécrire de mémoire la fiche de formules essentielles une fois par semaine.</p><h3 id="phase-3-—-affutage-17–18-nov" tabindex="-1">Phase 3 — Affûtage (17–18 nov.) <a class="header-anchor" href="#phase-3-—-affutage-17–18-nov" aria-label="Permalink to &quot;Phase 3 — Affûtage (17–18 nov.)&quot;">​</a></h3><ul><li>Séries mixtes légères uniquement ; pas d’examen blanc complet.</li><li>Éthique, formules, erreurs récurrentes, étapes de calculatrice et logistique de l’examen.</li><li>Protéger le sommeil ; n’ajouter aucune nouvelle ressource.</li></ul><h2 id="modele-de-bilan-hebdomadaire" tabindex="-1">Modèle de bilan hebdomadaire <a class="header-anchor" href="#modele-de-bilan-hebdomadaire" aria-label="Permalink to &quot;Modèle de bilan hebdomadaire&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>Heures prévues / réalisées :</span></span>
<span class="line"><span>Progrès FSA / Éthique / autres matières :</span></span>
<span class="line"><span>Questions tentées / taux de réussite :</span></span>
<span class="line"><span>Matière la plus faible et type d’erreur :</span></span>
<span class="line"><span>Un concept que je peux maintenant enseigner :</span></span>
<span class="line"><span>Un changement pour la semaine prochaine :</span></span></code></pre></div><h2 id="les-sept-prochains-jours-14–20-oct" tabindex="-1">Les sept prochains jours (14–20 oct.) <a class="header-anchor" href="#les-sept-prochains-jours-14–20-oct" aria-label="Permalink to &quot;Les sept prochains jours (14–20 oct.)&quot;">​</a></h2><ul><li>[ ] Finir les questions de fin de chapitre de FSA M1 et commencer <strong>M2 Rémunération des salariés</strong>.</li><li>[ ] Avancer FSA M3–M6 (des ébauches suffisent pendant le rattrapage).</li><li>[ ] Poursuivre l’Éthique après II(A) ; faire une courte série d’Éthique dans la semaine.</li><li>[ ] Boucler la moitié restante d’Économie.</li><li>[ ] Atteindre le point d’étape du dim. 18 : premier passage FSA ≥80–100 % + questions de fin de chapitre ; Éthique en cours ; Économie bouclée.</li><li>[ ] D’ici le lun. 20 : commencer le premier passage des Actions (début de la semaine du 19 au 25 oct.).</li></ul>`,31)])])}const h=t(i,[["render",n]]);export{p as __pageData,h as default};
